Func<Orc.Game.Damage.DamageApplyView, Context, CancellationToken, Task> Handle = async (view, ctx, ct) =>
{
    if (view.Host is not Orc.Game.Cards.UnitCard host) { return; }
    if (!object.ReferenceEquals(view.Target, host)) { return; }
    if (!host.Keywords.Has("强磁护盾")) { return; } // 无强磁护盾＝无效

    // 海绵装甲：最终伤害值至多 1（在强磁护盾 -1 之后封顶）。
    if (view.Amount > 1) { view.Amount = 1; }
};
